SELECT DISTINCT od.device_code as parentDeviceCode, ( case when length(IFNULL(ten.channel_name, '')) = 0 then t.channel_name else ten.channel_name end ) channelName, t.channel_code, t.channel_status as status, t.visual_range, t.horiz_range, t.verti_range
,od.tenant_id
FROM vm_order_devices od LEFT JOIN vm_channel_info_t t on od.device_code = t.device_code LEFT JOIN vm_tenant_device_channel_rel_t ten on od.device_code = ten.device_code and ten.tenant_id = #{tenantId} od.tenant_id and t.channel_code = ten.channel_code and ten.industry_code = #{industryCode} od.industry_code and ten.delete_flag='0'
AND t.channel_code= #{channelCode}
and od.device_code in
#{item}
AND od.device_code= #{deviceCode}
AND od.tenant_id= #{tenantId}
and od.industry_code = #{industryCode}
ORDER BY t.channel_code

SELECT DISTINCT od.device_code as parentDeviceCode, ( case when length(IFNULL(ten.channel_name, '')) = 0 then t.channel_name else ten.channel_name end ) channelName, t.channel_code, t.channel_status as status, t.visual_range, t.horiz_range, t.verti_range FROM vm_device_info_t od LEFT JOIN vm_channel_info_t t on od.device_code = t.device_code LEFT JOIN vm_tenant_device_channel_rel_t ten on od.device_code = ten.device_code and ten.tenant_id = #{tenantId} and t.channel_code = ten.channel_code and ten.industry_code = #{industryCode} and ten.delete_flag='0'
AND t.channel_code= #{channelCode}
and od.device_code in
#{item}
AND od.device_code= #{deviceCode}
